import{_ as e,c as l,aU as a,a as d}from"./chunks/framework.DIXiA2XH.js";const i="/assets/%E4%B8%AA%E4%BA%BA%E6%89%80%E5%BE%97%E7%A8%8E.Dpzdye7B.jpg",o=JSON.parse('{"title":"个人所得税","description":"","frontmatter":{},"headers":[],"relativePath":"note/knowledge/01-个人所得税.md","filePath":"note/knowledge/01-个人所得税.md","lastUpdated":1785161057000}'),s={name:"note/knowledge/01-个人所得税.md"};function n(p,t,f,g,x,r){return d(),l("div",null,[...t[0]||(t[0]=[a('<h1 id="个人所得税" tabindex="-1">个人所得税 <a class="header-anchor" href="#个人所得税" aria-label="Permalink to &quot;个人所得税&quot;">​</a></h1><h2 id="个人所得税-1" tabindex="-1">个人所得税 <a class="header-anchor" href="#个人所得税-1" aria-label="Permalink to &quot;个人所得税&quot;">​</a></h2><p>实发工资 = 税前工资 - 个人所得税 - 社保/公积金</p><p>全年累计应纳税额 = sum(本年税前工资) - n x 5000元(最低免税金额) - 本年累计专项扣除</p><p>当月个人所得税 = （全年累计应纳税额 * 税率 - 速算扣除数） - 已申报的个税</p><ul><li>减5000元是规定死的，因为每月工资不超过5000的话不需要扣个人所得税</li><li>n 是当前月，一月份n=1 3月份就是n=3</li><li>本年累计专项扣除 就是 五险一金</li><li>税率这个是浮动变化的。要根据你全年累计应纳税额来计算</li><li>速算扣除数 是根据税率浮动的，具体看下图表</li></ul><p>看上去上面的公式有点麻烦，其实我举个例子大家就明白了。</p><p>假如小明的税前工资为2w,每月扣除的五险一金为1000元。</p><table tabindex="0"><thead><tr><th style="text-align:left;">月份</th><th style="text-align:left;">本年税前累计工资</th><th style="text-align:left;">本年累计最低免税金额</th><th style="text-align:left;">本年累计专项扣除（五险一金）</th><th style="text-align:left;">全年累计应纳税额</th><th style="text-align:left;">当月个税税率</th><th style="text-align:left;">速算扣除数</th><th style="text-align:left;">本年累计个人所得税</th><th style="text-align:left;">当月扣除的个税</th></tr></thead><tbody><tr><td style="text-align:left;">2024-01</td><td style="text-align:left;">20000</td><td style="text-align:left;">5000</td><td style="text-align:left;">1000</td><td style="text-align:left;">14000</td><td style="text-align:left;">3%</td><td style="text-align:left;">0</td><td style="text-align:left;">420</td><td style="text-align:left;">420</td></tr><tr><td style="text-align:left;">2024-02</td><td style="text-align:left;">40000</td><td style="text-align:left;">10000</td><td style="text-align:left;">2000</td><td style="text-align:left;">28000</td><td style="text-align:left;">3%</td><td style="text-align:left;">0</td><td style="text-align:left;">840</td><td style="text-align:left;">420</td></tr><tr><td style="text-align:left;">2024-03</td><td style="text-align:left;">60000</td><td style="text-align:left;">15000</td><td style="text-align:left;">3000</td><td style="text-align:left;">42000</td><td style="text-align:left;">10%</td><td style="text-align:left;">2520</td><td style="text-align:left;">1680</td><td style="text-align:left;">840</td></tr><tr><td style="text-align:left;">2024-04</td><td style="text-align:left;">80000</td><td style="text-align:left;">20000</td><td style="text-align:left;">4000</td><td style="text-align:left;">56000</td><td style="text-align:left;">10%</td><td style="text-align:left;">2520</td><td style="text-align:left;">3080</td><td style="text-align:left;">1400</td></tr></tbody></table><div class="tip custom-block github-alert"><p class="custom-block-title">这就是为什么有时候发工资的时候当月的比上个月少发好几百的原因，都是因为税率引起的。</p><p></p></div><p><img src="'+i+'" alt=""></p><h2 id="为什么工资条上面的个税和个税app上面的不一样" tabindex="-1">为什么工资条上面的个税和个税APP上面的不一样？ <a class="header-anchor" href="#为什么工资条上面的个税和个税app上面的不一样" aria-label="Permalink to &quot;为什么工资条上面的个税和个税APP上面的不一样？&quot;">​</a></h2><p>我猜大部分人都没注意这个问题，一般是当前月发上个月的工资，但是你看工资条的时候会发现，我上个月的工资个税和个税APP上申报的钱 不一致。这是什么原因呢？</p><div class="tip custom-block github-alert"><p class="custom-block-title">回答</p><p></p><p>根据当地税务主管机关规定，薪资实际发放日期所在月份为个税申报税属期，</p><p>2025年2月10号发放的1月薪资属于2月税属期，</p><p>2025年3月10号发放的2月薪资属于3月税属期，</p><p>2025年4月10号发放的3月薪资属于4月税属期，尚未申报</p><p>...</p><p>2026年1月10号发12月薪资属于1月税属期</p><p>也就是说，这里面有个时间差。但是总数是不变的！！！</p></div>',14)])])}const h=e(s,[["render",n]]);export{o as __pageData,h as default};
